	/* @Test */
	public void testReadMem()
    {
		using (GdbAndConnection conn = startAndConnectGdb())
{
			string target = which("expPrint");
			conn.execute("""
					file %s
					ghidra trace start
					%s
					break main
					run"""
					.formatted(target, INSTRUMENT_STOPPED));
			RemoteMethod readMem = conn.getMethod("read_mem");
			try (ManagedDomainObject<Trace> mdo = openTrace(projectName("expPrint"))) {
				tb = new ToyDBTraceBuilder(mdo.get());
				waitStopped();
				long snap = 0;
				long pcOff = Long.decode(conn.executeCapture("print/x $pc").split("=")[1].strip());
				TraceObject inf1 = Objects.requireNonNull(tb.obj("Inferiors[1]"));

				readMem.invoke(Map.ofEntries(
					Map.entry("inferior", inf1),
					Map.entry("range", tb.range(pcOff, pcOff + 10))));

				MemDump dump = parseHexDump(conn.executeCapture("x/10bx $pc"));
				assertEquals(pcOff, dump.address());
				assertEquals(10, dump.data().length);
				ByteBuffer buf = ByteBuffer.allocate(dump.data().length);
				tb.trace.getMemoryManager().getBytes(snap, tb.addr(dump.address()), buf);
				assertArrayEquals(dump.data(), buf.array());
			}
		}
	}

	/* @Test */
	public void testWriteMem()
    {
		using (GdbAndConnection conn = startAndConnectGdb())
{
			string target = which("expPrint");
			conn.execute("""
					file %s
					ghidra trace start
					%s
					break main
					run"""
					.formatted(target, INSTRUMENT_STOPPED));
			RemoteMethod writeMem = conn.getMethod("write_mem");
			try (ManagedDomainObject<Trace> mdo = openTrace(projectName("expPrint"))) {
				tb = new ToyDBTraceBuilder(mdo.get());
				waitStopped();
				long pcOff = Long.decode(conn.executeCapture("print/x $pc").split("=")[1].strip());
				TraceObject inf1 = Objects.requireNonNull(tb.obj("Inferiors[1]"));

				writeMem.invoke(Map.ofEntries(
					Map.entry("inferior", inf1),
					Map.entry("address", tb.addr(pcOff)),
					Map.entry("data", new byte[] { 1, 2, 3, 4 })));

				MemDump dump = parseHexDump(conn.executeCapture("x/4bx $pc"));
				assertEquals(pcOff, dump.address());
